// Progressive enhancement: content remains visible if motion APIs are unavailable.
const motionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');
const liveCopy={en:{label:'MEET LEDGRR',title:'A home for your<br><span>everyday numbers.</span>',copy:'Keep income and expenses in view with Ledgrr, the ledger app introduced by FinSolve. Pair your day-to-day records with the financial guidance your business needs.',cta:'Explore Ledgrr ↗',note:'Opens ledgrr.online in a new tab',demo:'ILLUSTRATIVE LEDGER',income:'Income',expenses:'Expenses',balance:'Balance',ready:'Your next step is ready.',progress:'answered',all:'All five answered. Your snapshot is ready.',hint:'Choose what best matches your routine.'},bn:{label:'লেডজারের সঙ্গে পরিচিত হন',title:'প্রতিদিনের হিসাবের<br><span>একটি সহজ ঠিকানা।</span>',copy:'ফিনসলভের পরিচয় করিয়ে দেওয়া লেডজার অ্যাপে আয় ও ব্যয়ের হিসাব নজরে রাখুন। প্রতিদিনের নথির সঙ্গে ব্যবসার জন্য প্রয়োজনীয় আর্থিক দিকনির্দেশনা যুক্ত করুন।',cta:'লেডজার দেখুন ↗',note:'নতুন ট্যাবে ledgrr.online খুলবে',demo:'হিসাবের উদাহরণচিত্র',income:'আয়',expenses:'ব্যয়',balance:'ব্যালেন্স',ready:'আপনার পরবর্তী পদক্ষেপ তৈরি।',progress:'টির উত্তর দেওয়া হয়েছে',all:'পাঁচটি উত্তর সম্পন্ন। আপনার ফলাফল তৈরি।',hint:'আপনার অভ্যাসের সঙ্গে মেলে এমন উত্তর বেছে নিন।'}};
const ledgrrSection=document.createElement('section');ledgrrSection.id='ledgrr';ledgrrSection.className='section ledgrr-section';document.getElementById('about').after(ledgrrSection);
const progress=document.createElement('div');progress.className='check-progress';progress.innerHTML='<div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="5" aria-valuenow="0"><i></i></div><p class="progress-caption" aria-live="polite"></p>';
document.querySelector('.assessment-head').after(progress);
function updateLiveCopy(){const bn=document.documentElement.lang==='bn',c=liveCopy[bn?'bn':'en'];ledgrrSection.innerHTML=`<div class="ledgrr-copy"><p class="eyebrow">${c.label}</p><h2>${c.title}</h2><p>${c.copy}</p><a class="button ledgrr-link" href="https://ledgrr.online/" target="_blank" rel="noopener">${c.cta}</a><small>${c.note}</small></div><div class="ledger-demo" aria-label="${c.demo}"><div class="ledger-top"><b><span class="ledger-mark" aria-hidden="true">L</span> Ledgrr</b><span>${c.demo}</span></div><div class="ledger-rows"><div><span class="ledger-dot income" aria-hidden="true">↗</span><span>${c.income}</span><b>৳ 84,200</b></div><div><span class="ledger-dot expense" aria-hidden="true">↙</span><span>${c.expenses}</span><b>৳ 31,450</b></div></div><div class="ledger-balance"><span>${c.balance}</span><b>৳ 52,750</b><svg viewBox="0 0 240 60" aria-hidden="true"><path d="M2 54 35 41 65 46 99 26 131 32 164 12 196 19 237 3" fill="none" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/></svg></div><div class="ledger-status"><span aria-hidden="true">✓</span> ${c.ready}</div></div>`;updateCheckProgress();}
function updateCheckProgress(){const count=document.querySelectorAll('#questions input:checked').length;const c=liveCopy[document.documentElement.lang==='bn'?'bn':'en'];const bar=progress.querySelector('[role=progressbar]');bar.setAttribute('aria-valuenow',count);bar.setAttribute('aria-label',document.documentElement.lang==='bn'?'প্রশ্নের অগ্রগতি':'Questions completed');bar.querySelector('i').style.width=`${count/5*100}%`;progress.querySelector('p').textContent=count===5?c.all:`${count}/5 ${c.progress} · ${c.hint}`;document.querySelectorAll('#questions fieldset').forEach(f=>f.classList.toggle('answered',!!f.querySelector('input:checked')));document.querySelector('.assessment-head>span').textContent=`${count}/5`;document.querySelector('#check-form button[type=submit]').classList.toggle('ready',count===5);}
document.getElementById('questions').addEventListener('change',e=>{if(e.target.matches('input[type=radio]')){const field=e.target.closest('fieldset');field.classList.remove('choice-pop');void field.offsetWidth;field.classList.add('choice-pop');updateCheckProgress();}});
document.getElementById('check-form').addEventListener('reset',()=>requestAnimationFrame(()=>{document.querySelectorAll('#questions input').forEach(input=>{input.checked=false;input.defaultChecked=false;});updateCheckProgress();}));
new MutationObserver(updateCheckProgress).observe(document.getElementById('questions'),{childList:true});
new MutationObserver(updateLiveCopy).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
updateLiveCopy();
let revealObserver;
function registerReveals(){if(!('IntersectionObserver' in window)||motionPreference.matches)return;try{revealObserver??=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('layer-visible');entry.target.classList.remove('layer-pending');revealObserver.unobserve(entry.target);}},{threshold:.08,rootMargin:'0px 0px -20px 0px'});const targets=document.querySelectorAll('.section-head,.service,.about>div,.step,.ledgrr-copy,.ledger-demo,.check-section>div:first-child,.assessment,.consultation>div,.consultation form,.faq>div,.contact-banner>div');targets.forEach((el,i)=>{if(el.dataset.revealBound)return;el.dataset.revealBound='true';el.classList.add('unfold-layer');el.style.setProperty('--reveal-delay',`${el.classList.contains('service')?(i%3)*65:0}ms`);if(el.getBoundingClientRect().top>window.innerHeight)el.classList.add('layer-pending');revealObserver.observe(el);});}catch{document.querySelectorAll('.layer-pending').forEach(el=>el.classList.remove('layer-pending'));}}
registerReveals();new MutationObserver(registerReveals).observe(document.getElementById('service-grid'),{childList:true});motionPreference.addEventListener('change',()=>{if(motionPreference.matches){revealObserver?.disconnect();document.querySelectorAll('.layer-pending').forEach(el=>el.classList.remove('layer-pending'));}else registerReveals();});
const headerElement=document.querySelector('header');window.addEventListener('scroll',()=>headerElement.classList.toggle('has-scrolled',window.scrollY>15),{passive:true});
if('IntersectionObserver' in window){const navigationObserver=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){document.querySelectorAll('#nav a').forEach(a=>{if(a.hash==='#'+e.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}},{rootMargin:'-10% 0px -65% 0px'});document.querySelectorAll('section[id]').forEach(s=>navigationObserver.observe(s));}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('nav').classList.contains('open')){document.getElementById('nav').classList.remove('open');document.getElementById('menu').setAttribute('aria-expanded','false');document.getElementById('menu').focus();}});
